<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driver\Rest\ConsentPurposeAllowController;
use Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driver\Rest\ConsentPurposeListController;
use Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driver\Rest\ConsentPurposeCreateController;
use Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driver\Rest\ConsentPurposeRetrieveController;
use Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driver\Rest\ConsentPurposeUpdateController;
use Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driver\Rest\ConsentPurposeDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Service\Visibility\ConsentPurposeRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Service\Visibility\ConsentPurposeCollectNonEditableFields;
use Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driven\ConsentPurposeReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\ConsentPurpose\Infrastructure\Driven\ConsentPurposeWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeReadGateway;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeWriteGateway;

class ConsentPurposePlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[ConsentPurposeReadGateway::class] = \DI\autowire(ConsentPurposeReadRepositoryAdapter::class);
        $def[ConsentPurposeWriteGateway::class] = \DI\autowire(ConsentPurposeWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/consent-purposes', [$this, 'setRoutesForConsentPurpose']);
        $collector->group('/api/me/acl/access/consent-purposes', [$this, 'setRoutesForConsentPurposeAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(ConsentPurposeRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(ConsentPurposeCollectNonEditableFields::class, FixTenantExcludingRoot::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("consent-purpose", "list", "READ");
            $handler->registerResourceAction("consent-purpose", "create", "WRITE");
            $handler->registerResourceAction("consent-purpose", "retrieve", "READ");
            $handler->registerResourceAction("consent-purpose", "update", "WRITE");
            $handler->registerResourceAction("consent-purpose", "delete", "WRITE");

            $handler->registerResourceAttribute("consent-purpose", "tenant", "MANAGE");
            $handler->registerResourceAttribute("consent-purpose", "key", "MANAGE");
            $handler->registerResourceAttribute("consent-purpose", "title", "MANAGE");
            $handler->registerResourceAttribute("consent-purpose", "description", "MANAGE");
            $handler->registerResourceAttribute("consent-purpose", "required", "MANAGE");
            $handler->registerResourceAttribute("consent-purpose", "activationDate", "MANAGE");
            $handler->registerResourceAttribute("consent-purpose", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForConsentPurposeAcl(RouteCollectorProxy $consentPurposeGroup): void
    {
        $consentPurposeGroup->get('', [ConsentPurposeAllowController::class, 'genericAllow']);
        $consentPurposeGroup->get('/{uid}', [ConsentPurposeAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForConsentPurpose(RouteCollectorProxy $consentPurposeGroup): void
    {
        $consentPurposeGroup->get('', [ConsentPurposeListController::class, 'list']);
        $consentPurposeGroup->post('', [ConsentPurposeCreateController::class, 'create']);
        $consentPurposeGroup->get('/{uid}', [ConsentPurposeRetrieveController::class, 'retrieve']);
        $consentPurposeGroup->put('/{uid}', [ConsentPurposeUpdateController::class, 'update']);
        $consentPurposeGroup->delete('/{uid}', [ConsentPurposeDeleteController::class, 'delete']);
        $consentPurposeGroup->delete('', [ConsentPurposeDeleteController::class, 'deleteAllForQuery']);
        $consentPurposeGroup->get('/~/delete-status/{uid}', [ConsentPurposeDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
